import ipaddress
import logging

from taf.fdsw.rc.interfaces.exceptions import OperationFailure
from taf.fdsw.rc.schemas.FDSW18SP.autoconnection import (
    AutoConnection18SP, Site_Identification18SP)

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ValidationPreChecks():

    @staticmethod
    def validate_ip_address(address):
        """
        Checks if it is a valid IPv4 or IPv6 address Otherwise, raises value error.

        :param address: Ipv4 or IPv6 address
        """
        ipaddress.ip_address(address.encode().decode())
        logger.debug("given address {}".format(address))

    @staticmethod
    def check_prefix_length(prefix_length):
        """
        Checks if it is a valid IPv4 or IPv6 prefix length Otherwise, raises value error.

        :param prefix_length: Ipv4[0-31] or IPv6[0-126] prefix length
        """
        if prefix_length in range(0, 127):
            logger.debug(" %s is in the range" % str(prefix_length))
        else:
            raise ValueError("The number is outside the given range, please enter correct IPv6 or Ipv4 range length")

    @staticmethod
    def validate_vlan_id(vlan_id):
        """
        Checks if it is a valid vlan ID Otherwise, raises value error.

        :param vlan_id: vlan ID[1-4094]
        """
        if vlan_id in range(1, 4095):
            logger.debug(" %s is in the range" % str(vlan_id))
        else:
            raise ValueError("The number is outside the given range, please enter correct vlan ID range")


class AutoConfiguration():

    def __init__(self, client):
        self._client = client

    def autoconnection_parameters(self, timeout=10):
        autoconnection = self._client.send(
            method='config.autoconnection.fetch',
            timeout=timeout,
            parameters={})
        if autoconnection.status is False:
            error_msg = "Get autoconnection parameters information is not available {}, error {}"
            raise OperationFailure(error_msg)
        return autoconnection

    def get_autoconnection_parameters(self, timeout=10):
        autoconnection = self.autoconnection_parameters()
        get_autoconnection_parameters = AutoConnection18SP.from_object_dict(data=autoconnection.data)
        return get_autoconnection_parameters.to_dict()

    def _auto_configuration_pre_checks(self, primary_ip_address, primary_prefix_length, primary_gateway,
                                       identification_entity_ip_address, secondary_ip_address,
                                       secondary_prefix_length, secondary_vlan_id, ip_address,
                                       vpn_gateway_ip_address, primary_vlan_id=None, sec_gateway=None, vlan_id=None):
        if (primary_ip_address
            and primary_prefix_length
            and primary_gateway
            and identification_entity_ip_address
            and secondary_ip_address
            and secondary_prefix_length
            and secondary_vlan_id
            and ip_address
            and sec_gateway
            and vlan_id
            and primary_vlan_id
            and vpn_gateway_ip_address) \
                is None:
            logger.debug("default values, do nothing")
        else:
            ValidationPreChecks.validate_ip_address(address=primary_ip_address)
            ValidationPreChecks.check_prefix_length(prefix_length=primary_prefix_length)
            ValidationPreChecks.validate_ip_address(address=primary_gateway)
            ValidationPreChecks.validate_ip_address(address=identification_entity_ip_address)
            ValidationPreChecks.validate_ip_address(address=secondary_ip_address)
            ValidationPreChecks.check_prefix_length(prefix_length=secondary_prefix_length)
            ValidationPreChecks.validate_vlan_id(vlan_id=secondary_vlan_id)
            ValidationPreChecks.validate_ip_address(address=ip_address)
            ValidationPreChecks.validate_ip_address(address=sec_gateway)
            ValidationPreChecks.validate_vlan_id(vlan_id=vlan_id)
            ValidationPreChecks.validate_vlan_id(vlan_id=primary_vlan_id)
            ValidationPreChecks.validate_ip_address(address=vpn_gateway_ip_address)

    def set_site_identification(self, autoconnection_site_id, timeout=10):
        raise NotImplementedError

    def get_site_identification_siteId(self, timeout=10):
        raise NotImplementedError

    def get_site_identification_info(self, timeout=10):
        get_site_identification_info = self._client.send(
            method='config.identification.fetch',
            timeout=timeout,
            parameters={})
        if get_site_identification_info.status is False:
            error_msg = "Get identification siteId information is not valid. Error: {}"
            raise OperationFailure(error_msg)
        get_site_identification_info = Site_Identification18SP.from_object_dict(data=get_site_identification_info.data)
        return get_site_identification_info.to_dict()

    def enable_autoconfiguration_service(self, timeout):
        resp = self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"autoConfigurationMode": "Automatic"}
        )
        if resp.status is False:
            raise OperationFailure(resp.error)

    def disable_autoconfiguration_service(self, timeout):
        resp = self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"autoConfigurationMode": "Manual"}
        )
        if resp.status is False:
            raise OperationFailure(resp.error)
